import{_ as i,o as a,c as e,ah as t}from"./chunks/framework.ojwJKwrc.js";const r=JSON.parse('{"title":"celox CLIでcocotbを使う","description":"","frontmatter":{},"headers":[],"relativePath":"ja/guide/cocotb.md","filePath":"ja/guide/cocotb.md"}'),l={name:"ja/guide/cocotb.md"};function o(p,s,h,n,c,d){return a(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="celox-cliでcocotbを使う" tabindex="-1">celox CLIでcocotbを使う <a class="header-anchor" href="#celox-cliでcocotbを使う" aria-label="Permalink to &quot;celox CLIでcocotbを使う&quot;">​</a></h1><p>CeloxはVerylの設計を、VPI経由で通常の <a href="https://www.cocotb.org/" target="_blank" rel="noreferrer">cocotb</a> テストを実行できるネイティブ実行ファイルへ コンパイルできます。生成物にはコンパイル済み設計とCeloxランタイムが含まれるため、 実行時にVerylソースは不要です。</p><h2 id="cliをビルドする" tabindex="-1">CLIをビルドする <a class="header-anchor" href="#cliをビルドする" aria-label="Permalink to &quot;CLIをビルドする&quot;">​</a></h2><p>現在、CLIはCeloxのソースツリーからビルドします。</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --release</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> celox-vpi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --bin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> celox</span></span></code></pre></div><p>利用するPython環境へcocotbをインストールします。</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cocotb</span></span></code></pre></div><p>リポジトリのdevcontainerにはcocotb 2.0.1とVerilatorがあらかじめ入っています。</p><h2 id="設計をコンパイルする" tabindex="-1">設計をコンパイルする <a class="header-anchor" href="#設計をコンパイルする" aria-label="Permalink to &quot;設計をコンパイルする&quot;">​</a></h2><p>Verylプロジェクト内のソースを1つ指定し、トップレベルモジュール名を渡します。</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">target/release/celox</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vpi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/Top.veryl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --top</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Top</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build/top-sim</span></span></code></pre></div><p>Celoxはソースの位置から<code>Veryl.toml</code>を探し、プロジェクトのソースと依存関係を まとめてコンパイルします。Verylプロジェクト外の単独ソースを指定した場合は、 そのファイルだけをコンパイルします。<code>-o</code>を省略した出力先は<code>celox.out</code>です。</p><h2 id="cocotbを実行する" tabindex="-1">cocotbを実行する <a class="header-anchor" href="#cocotbを実行する" aria-label="Permalink to &quot;cocotbを実行する&quot;">​</a></h2><p>たとえば<code>test/test_top.py</code>にcocotbテストがある場合、そのモジュールをimportできる 状態で生成物を起動します。</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PYTHONPATH</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">test</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> build/top-sim</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test-module</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test_top</span></span></code></pre></div><p>生成された実行ファイルは自動的に次を行います。</p><ul><li><code>python3</code>からcocotbのVPIアダプターとlibpythonを検出する</li><li>コンパイル済みのトップレベル名をcocotbへ渡す</li><li><code>results.xml</code>を出力し、テスト失敗時は非ゼロで終了する</li></ul><p>別のPython環境や結果ファイルを使う場合は明示できます。</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">build/top-sim</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --test-module</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test_top</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .venv/bin/python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --results-file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build/results.xml</span></span></code></pre></div><p><code>--test-filter REGEX</code>で一致するテストに絞れます。cocotbの従来形式向けに <code>--testcase NAME</code>も利用できます。<code>--vpi PATH</code>を指定するとVPIアダプターの自動検出を 上書きします。既存の自動化向けに、<code>PYGPI_PYTHON_BIN</code>、<code>LIBPYTHON_LOC</code>、 <code>CELOX_COCOTB_VPI</code>、<code>COCOTB_TEST_MODULES</code>、<code>COCOTB_TEST_FILTER</code>、 <code>COCOTB_RESULTS_FILE</code>も引き続き利用できます。</p><h2 id="現在の互換範囲" tabindex="-1">現在の互換範囲 <a class="header-anchor" href="#現在の互換範囲" aria-label="Permalink to &quot;現在の互換範囲&quot;">​</a></h2><p>cocotb 2.0で使われるモジュール・信号の探索、immediate/deposit/force/release書き込み、 スカラー・ベクター値、シミュレーション時刻、およびStart、ReadWrite、ReadOnly、 NextTimeStep、Timer、ValueChange、Endの各コールバック領域に対応しています。</p><p>packed bit handle、遅延VPI書き込み、unpacked arrayのインデックス参照、 派生・カスケードクロックのスケジューリングにはまだ対応していません。</p>`,23)])])}const F=i(l,[["render",o]]);export{r as __pageData,F as default};
